export class AVC {
    static parseAVCDecoderConfigurationRecord(data: any): {
        sps: {
            codec: string;
            profileIdc: number;
            profileCompatibility: number;
            levelIdc: number;
            chromaFormat: number;
            width: number;
            height: number;
            sarRatio: number[] | undefined;
            fpsNum: number | undefined;
            fpsDen: number | undefined;
            fps: number | undefined;
            fixedFrame: boolean | undefined;
        } | undefined;
        spsArr: any[];
        ppsArr: any[];
        nalUnitSize: number;
    } | undefined;
    static parseSPS(unit: any): {
        codec: string;
        profileIdc: number;
        profileCompatibility: number;
        levelIdc: number;
        chromaFormat: number;
        width: number;
        height: number;
        sarRatio: number[] | undefined;
        fpsNum: number | undefined;
        fpsDen: number | undefined;
        fps: number | undefined;
        fixedFrame: boolean | undefined;
    };
}
